    private function getColumnId(String $column, String $name)
    {
        switch ($column) {
            case 'group':
                $model = Group::class;
                break;
            case 'division':
                $model = Division::class;
                break;
            default:
                $model = null;
                break;
        }

        if ($name === 'N/A') {
            return null;
        }

        $data = $model::where('name', $name)->first();

        return $data->id;
    }

